import sys; sys.path.insert(0, '/home/user/artificial-reef-survey/08_paper/data/src')
from common import *
SL = 'bunbury-airwave'
SH = '07_scale/shapes/bunbury-airwave/'
AL = dict(GLOBAL_ALIASES, ABC1219=r'ABC News \(2019-12-16/17\)', ABC0613=r'ABC News \(2019-06-13\)', Tracks1115=r'Tracks Magazine \(2019-11-15\)', BunburyMail=r'Bunbury Mail', Bakalo2026=r'Bakalo, L\. \(2026\)', GHD2021=r'GHD \(2021\)', Lidar=r'Lidar2009TRBS', RWRProfile=r'Raised Water Research\. "Bunbury Airwave"', RWRTear=r'Raised Water Research \(2019-12-16\)', Stab=r'Stab Magazine / The Inertia')
def build():
    r = Reef(SL, AL)
    r.F('name', 'Bunbury Airwave (inflatable bladder surf reef), Back Beach, Bunbury, Western Australia', 'text', 'S', 'ABC1219', 'ABC News 2019-12-16/17')
    r.F('country', 'Australia', 'text', 'S', 'ABC1219', 'ABC News 2019-12-16/17')
    r.F('lat', -33.3276, 'deg N (WGS84)', 'A', 'repo:' + SH + 'shape.json location_note.approx_centre_latlon', 'ESTIMATED centre, +-100 m: 45 m seaward of the waterline south of the Back Beach SLSC (text of ABC/RWR); NOT traced', note='Page marks approximate (location_note). The reef is not visible on any image.')
    r.F('lon', 115.6284, 'deg E (WGS84)', 'A', 'repo:' + SH + 'shape.json location_note.approx_centre_latlon', 'as lat')
    r.F('year_built', 2019, 'year (installation attempted Dec 2019; failed)', 'S', 'ABC1219', 'bladder tore during installation, mid-Dec 2019')
    r.U('year_completed', 'year', 'installation never completed; a second prototype was planned for Dec 2020 (needing ~A$300,000), a "back in the water for Summer 2024" promise (2022) and later a granite-reef proposal; none confirmed.')
    r.F('purpose', 'surf', 'category', 'S', 'ABC0613', 'card purpose: create a reliable wave on a closeout beach, tourism/competitions')
    r.F('material', 'inflatable dome-shaped Hypalon rubber bladder, glued seams, ballasted with ~140-150 t of washed coarse beach sand plus air (final design per the founder: sand-filled instead of air)', 'text', 'S', 'Tracks1115+Bakalo2026', 'Tracks 2019-11-15; Bakalo interview 2026')
    r.F('volume_m3', 105, 'm3 (spherical cap, mid of 92.6 m3 at H = 1.6 m and 117.3 m3 at H = 2.0 m)', 'D', 'repo:' + SH + '3d/METHODS_3D.md KN "Volume (cap) vs fill"', 'cap volume of the model; sand fill 140-150 t = 70-94 m3 at 1.6-2.0 t/m3', alts=[(112.1, 'footprint 112.1 m2 (traced circle D = 12 m)', 'D', 'repo:' + SH + 'shape.json', 'area, not volume (for reference)'), (82, 'sand fill 145 t / 1.77 t/m3 (DERIVED)', 'D', 'Tracks1115', 'METHODS_3D KN')])
    r.F('footprint_area_m2', 112.1, 'm2 (circle D = 12 m, 29-vertex trace of the drone photo)', 'D', 'repo:' + SH + 'shape.json canonical.area_m2', 'stated 12 m diameter = 113.1 m2; the drone photo has no scale bar, so the 12 m is the text value')
    r.F('plan_length_alongshore_m', 12.07, 'm', 'D', 'repo:' + SH + 'shape.json canonical.bbox_m.alongshore', 'diameter 12 m (text)')
    r.F('plan_length_crossshore_m', 12.09, 'm', 'D', 'repo:' + SH + 'shape.json canonical.bbox_m.crossshore', 'diameter 12 m (text)')
    r.F('reef_height_m', 2.0, 'm (range 1.6-2.0)', 'S', 'ABC0613', '2 m (ABC, RWR) vs 1.6 m "at the highest point" (Tracks 2019-11-15); design figures before installation, no as-installed measurement', note='All figures are design values stated before installation.')
    r.F('crest_depth_msl_m', 0.68, 'm below MSL (H = 2.0 m; 1.08 m at H = 1.6 m)', 'D', 'Lidar+GHD2021', 'model: seabed at the reef centre -2.68 m MSL (WA DoT lidar 2009 -2.58 m AHD, AHD-MSL offset from GHD 2021) minus H = 2.0 m; text: "shallow point about 1 m under the surface at low tide" (RWR)',
        note='Monte Carlo 0.69 +- 0.66 m below MLLW (METHODS_3D KN). 0.38-0.78 m below MLLW at H = 2.0-1.6 m.')
    r.F('crest_depth_lat_m', -0.02, 'm below LAT (about 0: at LAT the crest is at the surface for H = 2.0 m)', 'D', 'GHD2021', 'LAT -0.7 m MSL (GHD 2021 Table 1, Port of Bunbury, rounded 0.1 m); 0.68 - 0.70 = -0.02 m (H = 1.6 m: 0.38 m below LAT)')
    r.F('seabed_depth_toe_m', 2.92, 'm below MSL', 'D', 'Lidar', 'bed at the seaward edge of the bladder: 2.68 m at the reef centre (y = 37.5 m) + 6 m x 1/24.5 (lidar bed slope 1:24.5; METHODS_3D KN "Side slopes / profile")')
    r.F('seabed_depth_at_crest_m', 2.68, 'm below MSL', 'D', 'Lidar', 'seabed at the reef centre (y = 37.5 m), WA DoT lidar 2009 (-2.58 m AHD); Navionics agrees to 0.32 m RMS once read below LAT')
    r.F('distance_offshore_crest_m', 37.5, 'm (centre of the bladder from the waterline; text: 30-45 m)', 'D', 'repo:' + SH + 'shape.json canonical.distance_offshore_m', 'model default centre y = 37.5 m', alts=[(45, 'text: 30-45 m offshore', 'S', 'ABC0613', 'card size field')])
    r.F('depth_gap_m', 2.24, 'm', 'D', 'repo:' + SH + '3d/METHODS_3D.md KN', 'toe depth 2.92 - crest depth 0.68 (H = 2.0 m)')
    r.F('seaward_ramp_length_m', 6.0, 'm', 'D', 'repo:' + SH + 'shape.json', 'radius of the 12 m circle: toe (edge) to crest (centre of the spherical cap, stand-in shape; rim angle 36.9 deg at VE 1)', note='The real profile is unknown (Tracks 2021 calls the first bladder a "skateboard ramp" profile).')
    r.F('mean_seaward_slope', 0.373, 'm/m', 'D', 'repo:' + SH + '3d/METHODS_3D.md KN', '= 2.24 / 6.0 (1:2.7); the cap rim angle is 36.9 deg (tan = 0.75)')
    sp = round(0.1 - (-0.3), 2); mean = round(((0.1 + 0.0) / 2) - ((-0.3 + -0.1) / 2), 2)
    r.F('tide_spring_range_m', 1.2, 'm (predicted annual range, approx. LAT-HAT; NOT a spring range)', 'D', 'repo:Government of Western Australia, Department of Transport / Bureau of Meteorology (2026). Tide Predictions by Location, WA 2026 (heights above LAT). https://transport.wa.gov.au/getmedia/482d7b83-1a48-4220-9e2c-b07ebfcf8594/MAR_P_2026_Tide_Predictions_by_Location_WA.pdf (downloaded 2026-10-19; extremes extracted by script from 3 of 4 quarterly blocks, so they are lower bounds of the true annual extremes). Checked in 08_paper/notes/tides_check.md', 'Bunbury 2026 predicted extremes above LAT: max 1.30, min 0.10 -> 1.20 m (2024: 1.24 - 0.12 = 1.12 m); GHD 2021 HAT +0.5 / LAT -0.7 m MSL (1.2 m) agrees; field name kept for the pipeline, the quantity is the annual range', note='Replaces 0.4 m (MHHW +0.1 - MLLW -0.3 m MSL, GHD 2021 Table 1), which understated the range (the GHD MHHW is below the typical predicted highs). Micro-tidal (< 2 m). Sample day 1 Jan 2026: LW 0.16, HW 1.09 m above LAT (daily range 0.93 m); no typical daily range was extracted. Lower bound (3 of 4 quarterly blocks parsed).',
        alts=[(0.4, 'MHHW - MLLW, GHD 2021 Table 1 (superseded)', 'D', 'GHD2021', 'MHHW +0.1, MLLW -0.3 m MSL, rounded to 0.1 m')])
    r.F('tide_mean_range_m', mean, 'm (MHW - MLW, GHD 2021; likely understated, unverified)', 'D', 'GHD2021', 'MHLW -0.1, MLHW 0.0 m MSL: MHW = (MHHW+MLHW)/2 = +0.05, MLW = (MLLW+MHLW)/2 = -0.20', note='tides_check 2026-10-19: GHD MHHW is below the predicted highs and a sample day has a 0.93 m range, so this 0.25 m is probably too small; not recomputed (needs a column-aware parse of the WA predictions).')
    r.U('swell_hs_m', 'm', 'no wave-climate statement recorded; reef sited on a beach "with swell but poor bathymetry (closeouts)"; the only quantified wave: 0.75 m during the brief partial installation (Bottegal, Bunbury Mail 2022).')
    r.U('swell_tp_s', 's', 'not found.')
    r.U('swell_dir', 'text', 'not found.')
    r.F('design_wave', 'dome reef designed to turn closeouts into a peeling wave; UWA 12-month study planned but apparently never started', 'text', 'S', 'Tracks1115', 'card outcome field')
    r.U('arm_angle_to_shoreline_deg', 'deg', 'not applicable: circular dome.')
    r.U('arm_angle_to_swell_deg', 'deg', 'not applicable.')
    r.F('surf_outcome', 'does not work', 'category', 'S', 'ABC1219+BunburyMail', 'ABC 2019-12-16/17; Bunbury Mail 2022-03-22', note='Installation failed: the bladder tore along a glued seam when ~90 % complete and was removed within ~3 days. During the brief period in the water "a wave did break on it ... peeled nearly all the way to the beach ... a 0.75 metre wave" (Bottegal, Bunbury Mail 2022). No validated trial.')
    r.U('surfable_days_per_year', 'days/yr', 'none (never operational).')
    r.F('durability', 'bladder torn along a glued seam during installation (Dec 2019), removed within ~3 days (one source: half a day); second prototype only planned; developer later proposed a granite reef instead', 'text', 'S', 'ABC1219+RWRTear', 'ABC 2019-12; RWR 2019-12-16; card status_now')
    r.U('sediment_shoreline_outcome', 'text', 'none (never operational).')
    r.F('cost_local', 400000, 'USD', 'S', 'Stab', 'card cost field (R3, R10): total ~US$400,000 including installation (another source US$350,000); City of Bunbury committed A$75,000', price_year=2019, currency='USD', note='Sources disagree (350k vs 400k).', alts=[(350000, 'other source', 'S', 'RWRProfile', 'card cost field'), (75000, 'City of Bunbury sponsorship, AUD (2019)', 'S', 'ABC0613', 'card cost field')])
    r.F('shape_on_page', 'shown', 'category', 'S', None, '04_build/data/reefs.json footprint.display = True (read only; circle traced on a drone photo, position estimated)')
    r.F('model_3d', 'yes: stand-in spherical cap on lidar seabed; confidence MEDIUM', 'text', 'S', None, SH + '3d/METHODS_3D.md s1, s6')
    return r
